 "content": "from collections import deque


def transform(grid):
    """Encode counts of the two T orientations as up to four fixed slots each."""
    h, w = len(grid), len(grid[0])
    seen = set()
    up = down = 0
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if (0 <= nx < h and 0 <= ny < w and
                            grid[nx][ny] == color and (nx, ny) not in seen):
                        seen.add((nx, ny))
                        q.append((nx, ny))
            if color != 2 or len(cells) != 4:
                continue
            r0 = min(x for x, _ in cells)
            c0 = min(y for _, y in cells)
            shape = {(x - r0, y - c0) for x, y in cells}
            if shape == {(0, 1), (1, 0), (1, 1), (1, 2)}:
                up += 1  # stem points upward
            elif shape == {(0, 0), (0, 1), (0, 2), (1, 1)}:
                down += 1  # stem points downward

    out = [[0] * 6 for _ in range(3)]
    up_slots = ((0, 0), (0, 2), (2, 0), (2, 2))
    down_slots = ((0, 3), (0, 5), (2, 3), (2, 5))
    for r, c in up_slots[:up]:
        out[r][c] = 3
    for r, c in down_slots[:down]:
        out[r][c] = 1
    return out


if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
